package utp.siga.catalog.application.usecase; import java.util.*; import org.springframework.transaction.annotation.Transactional; import utp.siga.catalog.application.port.out.SupplierStore; import utp.siga.catalog.domain.model.*;
public class SupplierService { final SupplierStore s; public SupplierService(SupplierStore s){this.s=s;} @Transactional public Supplier create(Supplier x,UUID c){if(!x.active())throw new SupplierFieldValidationException("active");UUID id=s.create(x,c);return s.find(id).orElseThrow();} @Transactional(readOnly=true) public SupplierStore.Page page(int p,int z,String o,String q,Boolean a){return s.page(p,z,o,q,a);}@Transactional(readOnly=true) public Supplier get(UUID id){return s.find(id).orElseThrow(SupplierNotFoundException::new);}@Transactional public SupplierStore.Update update(Supplier x,long v,UUID c){try{return s.update(x,v,c);}catch(NoSuchElementException e){throw new SupplierNotFoundException();}}
}
